        data = self.data[-2:]
        if len(data) != 2:
            raise ValueError("Not enough bytes to pop a 16-bit integer.")
        self.data = self.data[:-2]
        return (data[0] << 8) | data[1]
    except Exception as e:
        raise ValueError(f"Error popping 16-bit unsigned integer: {str(e)}")

