def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from itertools import islice

    def chunks(iterable, size):
        iterator = iter(iterable)
        for first in iterator:
            yield chain([first], islice(iterator, size - 1))

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    processes = []
    results = []
    errors = []

    try:
        for chunk in chunks(varargs, _max_length // len(cmd)):
            full_cmd = cmd + tuple(chunk)
            if color and os.name == 'posix':
                process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE, text=False, bufsize=0, **kwargs, preexec_fn=os.setsid)
            else:
                process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE, text=False, bufsize=0, **kwargs)
            processes.append(process)

            if len(processes) >= target_concurrency:
                for process in processes:
                    stdout, stderr = process.communicate()
                    results.append(stdout)
                    if stderr:
                        errors.append(stderr)
                processes.clear()

        for process in processes:
            stdout, stderr = process.communicate()
            results.append(stdout)
            if stderr:
                errors.append(stderr)

        if errors:
            raise RuntimeError(b''.join(errors))

        return 0, b''.join(results)

    except Exception as e:
        return 1, str(e).encode('utf-8')

