    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("The application does not have a valid spec with a manifest.")

    for resource in app.spec.manifest:
        if resource not in app.spec.observers:
            # Generate default observer schema for the resource
            default_schema = {
