    """
    try:
        if self.in_style == 'named':
            if not isinstance(params, dict):
                raise ValueError("For named parameter style, params must be a dict.")
            out_params = {self.out_style + str(k): v for k, v in params.items()}
            formatted_sql = sql
            for key, value in out_params.items():
                placeholder = ':' + key
                if isinstance(sql, bytes):
                    placeholder = placeholder.encode()
                formatted_sql = formatted_sql.replace(self.out_style + str(key), placeholder)
        elif self.in_style in ('qmark', 'numeric', 'format', 'pyformat'):
            if not isinstance(params, Sequence) or isinstance(params, dict):
                raise ValueError("For ordinal parameter style, params must be a sequence.")
            out_params = [self.out_style + str(i) for i in range(len(params))]
            if self.in_style == 'qmark':
                placeholders = ('? ' * len(params)).rstrip()
            elif self.in_style == 'numeric':
                placeholders = ' '.join(f':{i + 1}' for i in range(len(params)))
            elif self.in_style == 'format':
                placeholders = ' '.join('%s' for _ in range(len(params)))
            else:  # pyformat
                placeholders = ' '.join(f'%({self.out_style + str(i)})s' for i in range(len(params)))
            formatted_sql = sql
            for out_placeholder, placeholder in zip(out_params, placeholders.split()):
                if isinstance(sql, bytes):
                    out_placeholder = out_placeholder.encode()
                    placeholder = placeholder.encode()
                formatted_sql = formatted_sql.replace(out_placeholder, placeholder)
        else:
            raise ValueError(f"Unsupported in-style parameter: {self.in_style}")

        return formatted_sql, out_params

