def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict

    try:
        package_data = defaultdict(list)
        for root, _, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    base_name = os.path.splitext(file)[0]
                    file_path = os.path.join(root, file)
                    package_data[base_name].append(file_path)
        return dict(package_data)
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    try:
        filename = file_path.split('/')[-1]
        file_folder = '/'.join(file_path.split('/')[:-1])

        if filename.startswith(prefix):
            if filename.endswith('.png') or filename.endswith('.jpg') or filename.endswith('.jpeg'):
                return {'type': 'asset', 'path': file_path}
            elif filename.endswith('.html') or filename.endswith('.pdf'):
                return {'type': 'rendition', 'path': file_path}
        return {'type': 'unknown', 'path': file_path}
    except Exception as e:
        return {'error': str(e)}

