def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            xml_data = {}
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = os.path.splitext(os.path.basename(file_info.filename))[0]
                    with z.open(file_info) as f:
                        content = f.read()
                    if base_name in xml_data:
                        xml_data[base_name].append(content)
                    else:
                        xml_data[base_name] = [content]
            return xml_data
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {zip_path} does not exist.")
    except zipfile.BadZipFile:
        raise ValueError(f"The file {zip_path} is not a valid zip file.")
    except Exception as e:
        raise Exception(f"An error occurred while processing the zip file {zip_path}: {str(e)}")

