def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        indentation = '  ' * indent
        result = f"{indentation}{self.__class__.__name__}("
        if debug:
            result += f"id={getattr(self, 'id', 'None')}, "
        attributes = {k: v for k, v in self.__dict__.items() if not k.startswith('_')}
        result += ', '.join(f"{k}={v!r}" for k, v in attributes.items())
        result += ")\n"
        return result
    except Exception as e:
        return f"{indentation}Error pretty printing {self.__class__.__name__}: {str(e)}\n"

