    """
    try:
        indent_str = '  ' * indent
        representation = f"{indent_str}{self.__class__.__name__}(\n"
        for attr, value in self.__dict__.items():
            if not attr.startswith('_'):
                if hasattr(value, 'pretty'):
                    representation += f"{indent_str}  {attr}={value.pretty(indent + 1, debug)},\n"
                else:
                    representation += f"{indent_str}  {attr}={value},\n"
        representation += f"{indent_str})"
        return representation
    except Exception as e:
        if debug:
            return f"{indent_str}{self.__class__.__name__}(Error: {str(e)})"
        else:
            return f"{indent_str}{self.__class__.__name__}()"

