def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for i, expr in enumerate(args):
        if len(expr) == 3:
            op = expr[1]
            left = expr[0]
            right = expr[2]
            if op == '&':
                if right[0] == '|' and right[1] == left:
                    new_args.append(left)
                elif right[0] == '|' and right[2] == left:
                    new_args.append(left)
                elif right[0] == '&' and right[1][0] == '~' and right[1][1] == left:
                    new_args.append(['&', left, right[2]])
                elif right[0] == '&' and right[2][0] == '~' and right[2][1] == left:
                    new_args.append(['&', left, right[1]])
                else:
                    new_args.append(expr)
            elif op == '|':
                if right[0] == '&' and right[1] == left:
                    new_args.append(left)
                elif right[0] == '&' and right[2] == left:
                    new_args.append(left)
                elif right[0] == '|' and right[1][0] == '~' and right[1][1] == left:
                    new_args.append(['|', left, right[2]])
                elif right[0] == '|' and right[2][0] == '~' and right[2][1] == left:
                    new_args.append(['|', left, right[1]])
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

