    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import deque

    def is_expr(expr):
        return isinstance(expr, tuple) and len(expr) == 3

    def absorption_law(expr, args):
        op = expr[0]
        left = expr[1]
        right = expr[2]

        if is_expr(left) and is_expr(right):
            if left[0] == op == right[0] and left[1] == right[1]:
                return left[1]

        for i in range(len(args)):
            arg = args[i]
            if is_expr(arg) and is_expr(left) and is_expr(right):
                if op == '&':
