                    if left[0] == '&' and arg[0] == '~' and left[2] == arg[1] and left[1] == right:
                        return expr[0], left[1], right
            elif is_expr(arg) and not is_expr(left) and is_expr(right):
                if op == '&':
                    if right[0] == '|' and right[1] == arg and right[2] == left:
                        return expr[0], right[2], left
                    if right[0] == '|' and right[2] == arg and right[1] == left:
