def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import deque

    def simplify(expr):
        stack = deque()
        for term in expr:
            if isinstance(term, tuple) and len(term) == 3:
                op, a, b = term
                if op == '&':
                    if b == (('|', a, '_')):
                        stack.append(a)
                    elif b == (('&', ('~', a), '_')):
                        stack.append(('&', a, b[2]))
                    else:
                        stack.append((op, a, b))
                elif op == '|':
                    if b == (('&', a, '_')):
                        stack.append(a)
                    elif b == (('|', ('~', a), '_')):
                        stack.append(('|', a, b[2]))
                    else:
                        stack.append((op, a, b))
            else:
                stack.append(term)
        return list(stack)

    return simplify(args)

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if not callable(func):
            raise ValueError(f"Expected a callable, got {type(func).__name__}")
        if not hasattr(self, '_registry'):
            self._registry = {}
        if hook not in self._registry:
            self._registry[hook] = []
        self._registry[hook].append(func)
        return func
    return decorator

