def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_rdelta = relativedelta()
    attributes = ['years', 'months', 'days', 'leapdays', 'weeks', 'hours', 'minutes', 'seconds', 'microseconds']
    for attr in attributes:
        value = getattr(self, attr, 0)
        if isinstance(value, float):
            int_part = int(value)
            decimal_part = value - int_part
            normalized_rdelta[attr] += int_part
            if decimal_part > 0:
                if attr == 'days':
                    normalized_rdelta.hours += int(decimal_part * 24)
                elif attr == 'hours':
                    normalized_rdelta.minutes += int(decimal_part * 60)
                elif attr == 'minutes':
                    normalized_rdelta.seconds += int(decimal_part * 60)
                elif attr == 'seconds':
                    normalized_rdelta.microseconds += int(decimal_part * 1e6)
        else:
            normalized_rdelta[attr] = value
    return normalized_rdelta

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import sys
        if sys.version_info[0] == 2:
            return tuple(name.encode('utf-8') if isinstance(name, unicode) else name for name in namefunc())
        else:
            return namefunc()
    except Exception as e:
        raise RuntimeError("Failed to process timezone names: " + str(e))

