def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    full_command = commands + args

    try:
        if verbose:
            print("Running command:", ' '.join(full_command))

        env = env or os.environ

        with subprocess.Popen(full_command, cwd=cwd, env=env, stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE, stdout=subprocess.PIPE) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)

        if verbose:
            print("Command output:", stdout.decode())

        return stdout.decode()

    except FileNotFoundError:
        raise ValueError(f"Command not found: {commands[0]}")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command failed with return code {e.returncode}: {e.stderr.decode()}") from e

