def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    def merge_into(target, source):
        for key, value in source.value:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                found = False
                for tkey, tvalue in target.value:
                    if isinstance(tvalue, ruamel.yaml.nodes.MappingNode) and key.value == tkey.value:
                        merge_into(tvalue, value)
                        found = True
                        break
                if not found:
                    target.value.append((key, value))
            else:
                target.value = [(k, v) for k, v in target.value if k.value != key.value] + [(key, value)]

    merged_dict = defaultdict(lambda: None)
    for key, value in nodes:
        if merged_dict[key.value] is None:
            merged_dict[key.value] = ruamel.yaml.nodes.MappingNode(tag=value.tag, value=[])
        merge_into(merged_dict[key.value], value)

    return list(merged_dict.items())

def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples, deep merge any node values corresponding to duplicate keys and return the result. If there are colliding keys with non-MappingNode values, the last of the values wins.'''
    from collections import defaultdict

    merged = defaultdict(lambda: (None, None))

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            if merged[key][0] is None:
                merged[key] = (key_node, value_node)
            else:
                # Deep merge the MappingNodes
                existing_key_node, existing_value_node = merged[key]
                existing_dict = {sub_key_node.value: sub_value_node for sub_key_node, sub_value_node in existing_value_node.value}
                new_dict = {sub_key_node.value: sub_value_node for sub_key_node, sub_value_node in value_node.value}
                existing_dict.update(new_dict)
                merged[key] = (existing_key_node, ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=list(existing_dict.items())))
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

