                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode

    merged = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key], MappingNode) and isinstance(value_node, MappingNode):
                # Deep merge the two MappingNodes
                merged_value = merged[key].value.copy()
                for sub_key_node, sub_value_node in value_node.value:
                    sub_key = sub_key_node.value
                    for i, (existing_key_node, existing_value_node) in enumerate(merged_value):
                        if existing_key_node.value == sub_key:
                            # Replace or merge the existing value node
                            if isinstance(existing_value_node, MappingNode) and isinstance(sub_value_node, MappingNode):
                                merged_value[i] = (existing_key_node, deep_merge_nodes([existing_value_node, sub_value_node])[0][1])
                            else:
                                merged_value[i] = (existing_key_node, sub_value_node)
                            break
                    else:
                        # Sub key not found, add it
                        merged_value.append((sub_key_node, sub_value_node))
                merged[key].value = merged_value
            else:
                # Last value wins for non-MappingNode values
                merged[key] = value_node
        else:
            merged[key] = value_node

    return [(key_node, value_node) for key_node, value_node in merged.items()]

