        # Catch any other exceptions that may occur during parsing
        return {"global": argparse.Namespace(error=str(e))}

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, MappingNode):
            if key not in merged_dict:
                merged_dict[key] = (key_node, MappingNode(tag=value_node.tag, value=[]))
            _, merged_value_node = merged_dict[key]
            merged_value_dict = {child[0].value: child for child in merged_value_node.value}
            for child_key_node, child_value_node in value_node.value:
                child_key = child_key_node.value
                if child_key in merged_value_dict:
                    if isinstance(child_value_node, MappingNode) and isinstance(merged_value_dict[child_key][1], MappingNode):
                        _, existing_child_value_node = merged_value_dict[child_key]
                        existing_child_value_dict = {existing_child[0].value: existing_child for existing_child in existing_child_value_node.value}
                        existing_child_value_dict.update({child[0].value: child for child in child_value_node.value})
                        existing_child_value_node.value = list(existing_child_value_dict.values())
                    else:
                        merged_value_dict[child_key] = (child_key_node, child_value_node)
                else:
                    merged_value_dict[child_key] = (child_key_node, child_value_node)
            merged_value_node.value = list(merged_value_dict.values())
        else:
            merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_value(existing, new):
        if isinstance(existing, MappingNode) and isinstance(new, MappingNode):
            existing_dict = {item[0].value: item[1] for item in existing.value}
            new_dict = {item[0].value: item[1] for item in new.value}
            merged_dict = existing_dict.copy()
            for key, value in new_dict.items():
                merged_dict[key] = merge_value(existing_dict.get(key), value)
            return MappingNode(tag=new.tag, value=[(ScalarNode(tag=key.tag, value=key.value), value) for key, value in merged_dict.items()])
        else:
            return new

    merged_dict = {}
    for key, value in nodes:
        merged_dict[key.value] = merge_value(merged_dict.get(key.value), value)

    return [(ScalarNode(tag=key.tag, value=key.value), value) for key, value in merged_dict.items()]

