def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.parsers
        import borgmatic.commands
    except ImportError as e:
        print(f"Failed to import borgmatic: {e}", file=sys.stderr)
        return

    def generate_completion(parser, cmd_name):
        completion = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for name, subparser in action.choices.items():
                    completion.append(generate_completion(subparser, f"{cmd_name} {name}"))
            else:
                for option_string in action.option_strings:
                    if action.nargs == 0:
                        completion.append(f"{option_string}")
                    else:
                        completion.append(f"{option_string} {{:}}")
        return f"_borgmatic_{cmd_name.replace(' ', '_')}() {{\nCOMPREPLY=( $(compgen -W \"{' '.join(completion)}\" -- ${{COMP_WORDS[COMP_CWORD]}}) )\nreturn 0\n}}\n"

    main_parser = borgmatic.parsers.generate_subparsers()
    completion_script = generate_completion(main_parser, "borgmatic")

    completion_script += "complete -F _borgmatic_borgmatic borgmatic\n"

    return completion_script

