        parser = borgmatic.commands.create_argument_parser()
        actions = get_parser_actions(parser)

        script = ["_borgmatic_completion() {", "    local cur prev opts", "    COMPREPLY=()", "    cur=\"${COMP_WORDS[COMP_CWORD]}\"", "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"", "    opts=\""]

        for action in actions:
            if isinstance(action, argparse._StoreTrueAction) or isinstance(action, argparse._StoreFalseAction):
                script.append(f"--{action.dest} ")
            elif action.option_strings:
                for option_string in action.option_strings:
                    script.append(f"{option_string} ")

        script.append(f"\"")

        script.extend([
            "    case ${prev} in",
            "        --*)",
            "            COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )",
            "            return 0",
            "            ;;",
            "    esac",
            "",
            "    COMPREPLY=( $(compgen -f -- ${cur}) )",
            "    return 0",
            "}",
            "",
            "complete -F _borgmatic_completion borgmatic"
        ])

        print("\n".join(script))

    except Exception as e:
        print(f"Error generating bash completion script: {e}")

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            namespace, extras = parser.parse_known_args(remaining_arguments)
            if any(vars(namespace).values()):  # If any argument was parsed
                parsed_results[subparser_name] = namespace
                remaining_arguments = extras
        except argparse.ArgumentError:
            continue

    return parsed_results, remaining_arguments

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    try:
        if not isinstance(response, list):
            raise ValueError("Response must be a list.")
        if not isinstance(max_results, int) or max_results <= 0:
            raise ValueError("max_results must be a positive integer.")

        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]
    except Exception as e:
        print(f"An error occurred: {e}")
        yield []

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    try:
        if size.endswith('K'):
            return int(size[:-1]) * 1000
        elif size.endswith('M'):
            return int(size[:-1]) * 1000 ** 2
        elif size.endswith('G'):
            return int(size[:-1]) * 1000 ** 3
        elif size.endswith('T'):
            return int(size[:-1]) * 1000 ** 4
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format. Please provide a size like '500K', '1M', etc.")

