def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclass_list = cls.__subclasses__()
    for subclass in subclass_list[:]:
        subclass_list.extend(subclasses(subclass))
    return subclass_list

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses_list = []

    def _subclasses(current_cls):
        nonlocal subclasses_list
        for subclass in current_cls.__subclasses__():
            subclasses_list.append(subclass)
            _subclasses(subclass)

    try:
        _subclasses(cls)
    except Exception as e:
        raise RuntimeError("Failed to retrieve subclasses") from e

    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    try:
        base = len(alphabet)
        number = 0
        for char in string:
            if char not in alphabet:
                raise ValueError(f"Character '{char}' not found in the provided alphabet.")
