                result.append(group)
                break

    return result

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    if not isinstance(tmp_path, Path):
        tmp_path = Path(tmp_path)

    tmp_path.mkdir(parents=True, exist_ok=True)

    if filename is None:
        filename = os.path.basename(archive_path)
    repo_path = tmp_path / filename

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(tmp_path)], check=True)
        else:
            raise ValueError("Unsupported archive format")

        return repo_path.as_uri()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}") from e

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    try:
        tmp_path = Path(tmp_path)
        tmp_path.mkdir(parents=True, exist_ok=True)

        if filename:
            output_path = tmp_path / filename
        else:
            output_path = tmp_path / Path(archive_path).stem

        if archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(output_path)], check=True)
        elif archive_path.endswith(('.tar', '.tar.gz', '.tgz')):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(output_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(output_path)], check=True)
        else:
            raise ValueError("Unsupported archive format")

        return f"file://{output_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'status', '--ignored', '--short'], capture_output=True, text=True, check=True)
