def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"Error computing Gaussian: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import configparser

    if overrides is None:
        overrides = {}

    config_dict = {}
    errors = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
        except (FileNotFoundError, PermissionError, configparser.ParsingError) as e:
            errors.append(logging.LogRecord(name='ConfigLoader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True))
            continue

        # Resolve environment variables if requested
        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    config.set(section, key, os.path.expandvars(value))

        # Apply overrides
        for section, section_overrides in overrides.items():
            if section in config:
                for key, value in section_overrides.items():
                    config.set(section, key, value)

        config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}

    return config_dict, errors

