    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os
    import configparser

    configurations = {}
    parse_errors = []

    for config_filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(config_filename) as f:
                config.read_file(f)
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=config_filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            parse_errors.append(record)
            continue

        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    try:
                        config.set(section, key, os.path.expandvars(value))
                    except Exception as e:
                        record = logging.LogRecord(
                            name='config_loader',
                            level=logging.ERROR,
                            pathname=config_filename,
                            lineno=0,
                            msg=f'Error resolving environment variables in [{section}]{key}: {e}',
                            args=(),
                            exc_info=True
                        )
                        parse_errors.append(record)

        if overrides:
            for section, settings in overrides.items():
                if section not in config:
                    config.add_section(section)
                for key, value in settings.items():
                    config.set(section, key, value)

        configurations[config_filename] = {section: dict(config.items(section)) for section in config.sections()}

    return configurations, parse_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import configparser

    configs = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)

                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            resolved_value = os.path.expandvars(value)
                            config.set(section, key, resolved_value)

                # Apply overrides
                for section, options in overrides.items():
                    if section in config:
                        for key, value in options.items():
                            config.set(section, key, str(value))

                configs[filename] = config

        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename,
                                                lineno=0, msg=f'Configuration file not found: {filename}', args=(), exc_info=True))
        except configparser.Error as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename,
                                                lineno=0, msg=f'Error parsing configuration file: {filename} - {str(e)}', args=(), exc_info=True))

    return configs, log_records

