def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self.scale_value is None or self.scale_value == 0:
            raise ValueError("Graph has unknown or zero scale.")
        return self.scale_value
    else:
        if self.scale_value is None or self.scale_value == 0:
            raise ValueError("Graph has unknown or zero scale, cannot rescale.")
        try:
            scale_factor = float(other) / self.scale_value
            for data_point in self.data:
                data_point[-1] *= scale_factor
                if len(data_point) > len(self.fields):
                    data_point[-2] *= scale_factor  # assuming errors are in the second last field
            self.scale_value = float(other)
        except (TypeError, ValueError):
            raise ValueError("Provided scale value must be a numeric type.")

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import zope.interface
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not claim to provide {iface}")

    required_attrs = iface.names()
    candidate_attrs = set(dir(candidate))

    for name in required_attrs:
        attr = iface[name]
        if isinstance(attr, zope.interface.Attribute):
            if name not in candidate_attrs:
                errors.append(f"{candidate} does not have required attribute {name}")
        elif isinstance(attr, zope.interface.Method):
            if name not in candidate_attrs:
                errors.append(f"{candidate} does not have required method {name}")
            else:
                candidate_method = getattr(candidate, name)
                if not inspect.ismethod(candidate_method) and not inspect.isfunction(candidate_method):
                    errors.append(f"{candidate}.{name} is not a method or function")
                else:
                    iface_method_signature = inspect.signature(attr.bind(candidate).value)
                    candidate_method_signature = inspect.signature(candidate_method)
                    if not _signature_compatible(iface_method_signature, candidate_method_signature):
                        errors.append(f"Signature of {candidate}.{name} does not match the required signature of {iface} interface")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def _signature_compatible(iface_signature, candidate_signature):
    iface_params = iface_signature.parameters
    candidate_params = candidate_signature.parameters

    if len(iface_params) > len(candidate_params):
        return False

    for name, iface_param in iface_params.items():
        if name not in candidate_params:
            return False
        candidate_param = candidate_params[name]
        if iface_param.kind != candidate_param.kind:
            return False
        if iface_param.default != candidate_param.default and iface_param.default is not inspect.Parameter.empty:
            return False

    return True

