def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    mcs = set()
    for base in bases:
        mcs.update(getattr(base, '__mro__', ()))
    if len(mcs) == 1:
        return mcs.pop()
    elif mcs:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all the metaclasses of its bases")
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        mc = type(base)
        if mc is not type:
            return mc
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        if isinstance(base, type):
            return type(base)
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        metaclass = getattr(base, "__metaclass__", type(base))
        if isinstance(metaclass, tuple):
            metaclasses.update(metaclass)
        else:
            metaclasses.add(metaclass)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Find a common metaclass among bases
    common_metaclass = None
    for metaclass in metaclasses:
        if common_metaclass is None or issubclass(common_metaclass, metaclass):
            common_metaclass = metaclass
        elif not issubclass(metaclass, common_metaclass):
            raise TypeError("Metaclass conflict: the metaclasses %s and %s have a common ancestor %s" %
                            (common_metaclass.__name__, metaclass.__name__, type.__name__))

    return common_metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metas = {type(base) for base in bases}
    if not metas:
        return type
    elif len(metas) == 1:
        return metas.pop()
    else:
        raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

