def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not dt.tzinfo:
        raise ValueError("The datetime object must be timezone-aware.")

    # Calculate the UTC timestamp
    utc_timestamp = dt.timestamp()

    # Convert the UTC timestamp to the target timezone
    target_dt = datetime.datetime.fromtimestamp(utc_timestamp, tz=self)

    # Determine if the datetime is in a fold state
    if self._isfold(target_dt):
        target_dt = self._resolve_fold(target_dt)

    return target_dt

def _isfold(self, dt):
    # Check if the datetime is in a fold state
    return self.localize(dt, is_dst=None) != self.localize(dt, is_dst=True)

def _resolve_fold(self, dt):
    # Resolve the fold by choosing the first occurrence chronologically
    try:
        return self.localize(dt, is_dst=False)
    except pytz.NonExistentTimeError:
        return self.localize(dt, is_dst=True)

